{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "An eligible student is a Tennessee resident entitled to attend public school, other than a student in a home school or a related church school.",
      "rationale": "Conveys residency and public-school eligibility, but omits the parental association or parent-teacher conditions limiting the church-related-school exclusion."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Scholarships could be used only at in-state private schools in approved categories I, II, or III.",
      "rationale": "Conveys the in-state private-school requirement and the approved school categories."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The department of education would run the program. Subject to appropriations, it would give scholarships to eligible students starting with the 2025-2026 school year.",
      "rationale": "Conveys department administration, funding contingency, eligible recipients, and the program's starting year and continuation."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "For 2025-2026, the department could award up to 20,000 scholarships in the order completed applications arrive. Half would go to students with household income up to 300% of the free or reduced price lunch limit, or students who meet certain definitions in two other code sections. The other half would be open to any eligible student.",
      "rationale": "Conveys the cap, allocation, income threshold, and application order, but leaves the alternative statutory eligibility groups unidentified and describes the required allocation as discretionary."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "From 2026-2027, the department could add up to 5,000 scholarships for the next year if applications exceed 75% of the scholarships available. If not, the cap stays the same.",
      "rationale": "Conveys the growth threshold, maximum increase, and unchanged-cap rule, but omits the funding contingency and application-period limitation."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "If applications exceed the number available, priority would go to: prior-year recipients; students at or below 100% of the lunch limit or those in the same two other categories; students at or below 300%; current public school students and incoming kindergartners; then all other eligible students. Within each group, earlier applications come first.",
      "rationale": "Conveys the main priority tiers, but does not identify the alternative statutory groups, omits the public-kindergarten eligibility qualification, and extends receipt-order priority to returning recipients."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "A student must apply, meet compulsory attendance rules through a private school, and not enroll in a public school during any year of a scholarship.",
      "rationale": "Conveys the application, compulsory-attendance, private-school enrollment, and public-school exclusion requirements without narrowing who may act for the student or which public schools are covered."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "The department could depart from this order to follow the result of an administrative appeal.",
      "rationale": "Conveys the department's authority to make out-of-order awards consistent with an administrative appeal."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "A scholarship would equal the state base funding amount and be paid only with state funds.",
      "rationale": "Conveys both the scholarship amount formula and exclusive state funding."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "Funds must first cover private school tuition and fees. Any remainder could go to listed expenses:",
      "rationale": "Conveys the tuition-and-fees priority and restriction of remaining funds to listed expenses."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "Funds must first cover private school tuition and fees. Any remainder could go to listed expenses: required textbooks, materials and uniforms;",
      "rationale": "Conveys payment after tuition and fees for required school materials, with curricula reasonably encompassed by materials."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "Any remainder could go to listed expenses: required textbooks, materials and uniforms; approved tutoring;",
      "rationale": "Conveys that remaining funds may pay for tutoring subject to approval requirements."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "Any remainder could go to listed expenses: required textbooks, materials and uniforms; approved tutoring; transportation fees;",
      "rationale": "Includes transportation expenses but omits travel to and from the enrolled private school and the qualifying fee-for-service provider requirement."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "Any remainder could go to listed expenses: required textbooks, materials and uniforms; approved tutoring; transportation fees; technology;",
      "rationale": "Includes technology expenses but omits department requirements and the restriction to the recipient's educational needs."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "summer and specialized afterschool academic programs (not childcare)",
      "rationale": "Conveys the program categories and childcare exclusion, but omits department requirements and the specified types of covered program expenses."
    },
    {
      "proposition_id": "P16",
      "status": "partial",
      "summary_quote": "early college courses, entrance exams, and industry credentials",
      "rationale": "Conveys several authorized expenses but omits early postsecondary opportunity examinations and departmental approval of industry credentials."
    },
    {
      "proposition_id": "P17",
      "status": "partial",
      "summary_quote": "and educational therapy.",
      "rationale": "Includes educational therapy as an authorized expense but omits the requirement that therapists meet department standards."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "Unused funds stay in the account across years. The account would close, and remaining money return to the state treasurer for future scholarships, on the earliest of",
      "rationale": "Conveys continued accounts and fund carryover subject to account-closure events."
    },
    {
      "proposition_id": "P19",
      "status": "partial",
      "summary_quote": "The account would close, and remaining money return to the state treasurer for future scholarships, on the earliest of high school graduation or equivalency, enrolling in public school, 13 school years, voluntary withdrawal, or disqualification.",
      "rationale": "Conveys closure, return of funds, and the main triggers, but omits approval of equivalency credentials and limits on disqualification to department action for program noncompliance."
    },
    {
      "proposition_id": "P20",
      "status": "partial",
      "summary_quote": "Recipients in grades 3 through 11 would have to take each year either a nationally standardized achievement test or the state TCAP test.",
      "rationale": "Conveys annual testing, grades, and alternatives, but omits instructional-plan alignment under state board rules and the grade-specific TCAP requirement."
    },
    {
      "proposition_id": "P21",
      "status": "full",
      "summary_quote": "Recipients in grades 3 through 11 would have to take each year either a nationally standardized achievement test or the state TCAP test. Private schools would give the tests and share results with parents.",
      "rationale": "Conveys private schools' annual administration duty and provision of results to parents."
    },
    {
      "proposition_id": "P22",
      "status": "partial",
      "summary_quote": "By each June 30, starting in 2026, they would give results to the comptroller's office of research and education accountability, which may accept aggregated, deidentified data.",
      "rationale": "Conveys the recipient office, deadline, and aggregated-data option, but omits the required form and analysis by grade, income, sex, and race."
    },
    {
      "proposition_id": "P23",
      "status": "full",
      "summary_quote": "That office would report yearly to the House and Senate education committees.",
      "rationale": "In context, conveys the office's annual reporting of assessment results to both chambers' education committees."
    },
    {
      "proposition_id": "P24",
      "status": "full",
      "summary_quote": "Participating private schools would be autonomous, not state agents.",
      "rationale": "Conveys both autonomy and non-agent status."
    },
    {
      "proposition_id": "P25",
      "status": "full",
      "summary_quote": "They would not have to change their creed, practices, admission or hiring policies, or curriculum. The program would not widen state or local authority to regulate them beyond rules narrowly tailored to enforce program requirements.",
      "rationale": "Conveys the limits on expanded regulation and protection of schools' institutional and educational choices."
    },
    {
      "proposition_id": "P26",
      "status": "full",
      "summary_quote": "A student in the existing education savings account pilot or the individualized education account program would be denied a scholarship for the same year.",
      "rationale": "Conveys the same-year participation bar for both named programs."
    },
    {
      "proposition_id": "P27",
      "status": "partial",
      "summary_quote": "Recipients would lose the right to special education services through the home district's individualized education program, but would have the same rights to equitable services as other private school students.",
      "rationale": "Conveys the loss of resident-district IEP entitlement and retention of equitable services, but omits related services and the individualized service plan mechanism."
    },
    {
      "proposition_id": "P28",
      "status": "full",
      "summary_quote": "It could not be paid directly to a recipient or parent.",
      "rationale": "Conveys the prohibition on direct scholarship payments to students or parents."
    },
    {
      "proposition_id": "P29",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not convey classification as a state or local public benefit."
    },
    {
      "proposition_id": "P30",
      "status": "full",
      "summary_quote": "The funds would not count as taxable income.",
      "rationale": "Conveys the program funds' exclusion from taxable income."
    },
    {
      "proposition_id": "P31",
      "status": "full",
      "summary_quote": "It must deny applicants who cannot show lawful presence in the United States.",
      "rationale": "Conveys mandatory department denial for failure to establish lawful presence."
    },
    {
      "proposition_id": "P32",
      "status": "partial",
      "summary_quote": "The department must write rules, including an appeal process for denied applications.",
      "rationale": "Conveys mandatory rulemaking and an appeals procedure, but omits compliance with the Uniform Administrative Procedures Act."
    },
    {
      "proposition_id": "P33",
      "status": "full",
      "summary_quote": "Starting with 2025-2026, if a district's state TISA funding falls below the prior year and its non-virtual average daily membership dropped, the state would add enough state funds to match the prior year.",
      "rationale": "Conveys the starting year, reduced-allocation and disenrollment conditions, and prior-year funding guarantee."
    },
    {
      "proposition_id": "P34",
      "status": "partial",
      "summary_quote": "From 2026-2027, the guarantee would build on prior additional amounts.",
      "rationale": "Conveys continuing protection incorporating supplemental funds, but omits the ever-received-funds eligibility condition and exact preceding-year combined funding benchmark."
    },
    {
      "proposition_id": "P35",
      "status": "partial",
      "summary_quote": "the state would add enough state funds to match the prior year. From 2026-2027, the guarantee would build on prior additional amounts. A district eligible under this and other provisions would receive only these funds.",
      "rationale": "Conveys state funding and an anti-stacking rule, but does not identify subsections (b) and (c), instead describing a broader exclusion of funds under other provisions."
    },
    {
      "proposition_id": "P36",
      "status": "partial",
      "summary_quote": "Subject to appropriation, the department would pay a one-time $2,000 state-funded bonus to each K-12 public school teacher employed in 2024-2025.",
      "rationale": "Conveys the amount, timing, funding, and appropriation condition, but omits the statutory existing-educator definition governing eligibility."
    },
    {
      "proposition_id": "P37",
      "status": "partial",
      "summary_quote": "It would not count as salary.",
      "rationale": "Conveys exclusion from salary treatment, but omits exclusion from TISA and from salary supplements for the specified statutory purpose."
    },
    {
      "proposition_id": "P38",
      "status": "partial",
      "summary_quote": "Section 4-49-104(e)(1) would be replaced so that 80% of the privilege tax collected goes to the state treasurer for an account for school districts' public school construction and maintenance.",
      "rationale": "Conveys the amendment target, percentage, destination, and use, but omits the council's distribution duty and the treasurer's administration of the account."
    },
    {
      "proposition_id": "P39",
      "status": "partial",
      "summary_quote": "The treasurer would consider economic distress, emergency or disaster damage, and other demonstrated need.",
      "rationale": "Conveys the general allocation factors, but omits designated distressed or at-risk county status, significant damage to existing school facilities, and LEA identification of other need."
    },
    {
      "proposition_id": "P40",
      "status": "full",
      "summary_quote": "The act has a severability clause.",
      "rationale": "Conveys preservation of independently operative provisions if another provision or application is invalid."
    },
    {
      "proposition_id": "P41",
      "status": "full",
      "summary_quote": "Section 5 would take effect July 1, 2025. The rest would take effect when it becomes law.",
      "rationale": "Conveys both effective dates and their respective scope."
    }
  ]
}
